import re, json, html, math

class Undefined:
    def __init__(self,name=''): self.name=name
    def __str__(self): return ''
    def __repr__(self): return 'undefined'
    def __bool__(self): return False
    def __getattr__(self,k): return Undefined(k)
    def __getitem__(self,k): return Undefined(str(k))

class Safe(str): pass

def truth(v): return bool(v)
def fmt(v):
    if isinstance(v, Undefined): return ''
    if v is None: return 'none'
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v, dict): return '{' + ', '.join(repr(k)+': '+fmt(x) for k,x in v.items()) + '}'
    if isinstance(v, (list,tuple)): return '['+', '.join(fmt(x) for x in v)+']'
    if isinstance(v, range): return '['+', '.join(map(str,v))+']'
    return str(v)

def attr(v,k):
    if isinstance(v, dict): return v.get(k, Undefined(k))
    try:
        if str(k).isdigit(): return v[int(k)]
        return getattr(v,k)
    except: return Undefined(k)

def filters(v,name,args):
    if name=='upper': return str(v).upper()
    if name=='lower': return str(v).lower()
    if name=='title': return str(v).title()
    if name=='capitalize': return str(v).capitalize()
    if name=='trim': return str(v).strip()
    if name=='default': return v if v and not isinstance(v,Undefined) else (args[0] if args else '')
    if name=='length': return len(v)
    if name=='first': return v[0] if v else Undefined()
    if name=='last': return v[-1] if v else Undefined()
    if name=='join': return (args[0] if args else '').join(map(str,v))
    if name=='replace': return str(v).replace(str(args[0]),str(args[1]))
    if name=='reverse': return list(reversed(v)) if not isinstance(v,str) else v[::-1]
    if name=='sort': return sorted(v)
    if name=='unique': return list(dict.fromkeys(v))
    if name=='list': return list(v)
    if name=='string': return fmt(v)
    if name=='int': return int(v)
    if name=='float': return float(v)
    if name=='abs': return abs(v)
    if name=='round': return round(v, int(args[0]) if args else 0)
    if name=='tojson':
        indent=args[0] if args and args[0] is not True else (2 if args else None)
        return Safe(json.dumps(v,ensure_ascii=False,separators=(',',':') if not indent else None,indent=indent))
    if name=='dictsort': return sorted(v.items(), key=lambda x:str(x[0]).lower())
    if name=='map':
        kw=args[0] if args and isinstance(args[0],dict) else {}
        if 'attribute' in kw: return [attr(x,kw['attribute']) for x in v]
        return list(v)
    if name in ('select','reject','selectattr','rejectattr'):
        isattr=name.endswith('attr'); reject=name.startswith('reject'); path=args[0] if isattr and args else None
        op=args[1] if isattr and len(args)>1 else None; target=args[2] if isattr and len(args)>2 else None
        out=[]
        for x in v:
            y=attr(x,path) if isattr else x
            ok=truth(y)
            if op:
                try: ok={'==':lambda:y==target,'!=':lambda:y!=target,'>':lambda:y>target,'>=':lambda:y>=target,'<':lambda:y<target,'<=':lambda:y<=target,'in':lambda:y in target}[op]()
                except: ok=False
            if ok != reject: out.append(x)
        return out
    return v

