"""Output escaping helpers for MiniJinja CLI rendering."""
import html
import json
import os


def mode_for_template(mode="auto", filename=None):
    """Resolve the auto mode from a template path's extension."""
    if mode != "auto":
        return mode
    ext = os.path.splitext(filename)[1] if filename else ""
    if ext in (".html", ".htm", ".xml", ".xhtml"):
        return "html"
    if ext in (".json", ".json5", ".yaml", ".yml"):
        return "json"
    return "none"


def escape_output(value, mode="none", filename=None, safe=False):
    """Render one interpolated value, honoring html/json autoescape modes."""
    mode = mode_for_template(mode, filename)
    if safe:
        return stringify(value)
    if mode == "json":
        # JSON autoescape is serialization of the interpolation, not HTML escaping.
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"))
    if mode == "html":
        return html.escape(stringify(value), quote=True)
    return stringify(value)


def stringify(value):
    if value is None:
        return "none"
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, range):
        return '[' + ', '.join(map(str, value)) + ']'
    if isinstance(value, (list, tuple)):
        return "[" + ", ".join(_display(v) for v in value) + "]"
    if isinstance(value, dict):
        return "{" + ", ".join(_display(k) + ": " + _display(v) for k, v in value.items()) + "}"
    return str(value)


def _display(value):
    if isinstance(value, str):
        return json.dumps(value, ensure_ascii=False)
    return stringify(value)

class AttrDict(dict):
    def __getattribute__(self, key):
        if not key.startswith('_') and key in self:
            return self[key]
        return super().__getattribute__(key)

def attrify(value):
    if isinstance(value, dict): return AttrDict({k: attrify(v) for k,v in value.items()})
    if isinstance(value, list): return [attrify(v) for v in value]
    if isinstance(value, tuple): return tuple(attrify(v) for v in value)
    return value

def truth(v): return bool(v)
def fmt(v):
    if isinstance(v, Undefined): return 'undefined'
    if v is None: return 'none'
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v, dict): return '{' + ', '.join(json.dumps(k,ensure_ascii=False)+': '+fmt(x) for k,x in v.items()) + '}'
    if isinstance(v, (list,tuple)): return '['+', '.join(json.dumps(x,ensure_ascii=False) if isinstance(x,str) else fmt(x) for x in v)+']'
    if isinstance(v, range): return '['+', '.join(map(str,v))+']'
    return str(v)

def attr(v,k):
    if isinstance(v, dict): return v.get(k, Undefined(k))
    try:
        if str(k).isdigit(): return v[int(k)]
        return getattr(v,k)
